{"command":"cat > src/main.rs <<'RS'
use std::collections::VecDeque;
use std::env;
use std::ffi::{OsStr, OsString};
use std::fs::File;
use std::io::{self, Read, Write};
use std::os::unix::ffi::OsStrExt;
use std::path::{Path, PathBuf};
use std::process::ExitCode;
use std::slice;

use clap::{Arg, ArgAction, Command};
use regex::bytes::{Regex, RegexBuilder};
use tempfile::NamedTempFile;

// ---------- errors ----------

#[derive(Debug)]
enum AppError {
    InvalidRegex(regex::Error),
    Ambiguous(Box<Ambiguous>),
    InvalidPath(PathBuf),
    Io(io::Error),
    FailedProcessing(Vec<(PathBuf, Box<dyn std::error::Error + Send + Sync>)>),
}

#[derive(Debug, Clone)]
struct Ambiguous {
    digits: String,
    remainder: String,
    // Position (in chars) of the first digit in the displayed text.
    digit_pos_chars: usize,
    candidate_len: usize,
    display_text: String,
}

impl std::fmt::Display for AppError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            AppError::InvalidRegex(e) => write!(f, "invalid regex {}", e),
            AppError::Ambiguous(a) => {
                write!(
                    f,
                    "The numbered capture group `${}` in the replacement text is ambiguous.\n\
                     hint: Use curly braces to disambiguate it `${{{}}}{}`.\n\
                     {}\n\
                     {}{}",
                    a.digits,
                    a.digits,
                    a.remainder,
                    a.display_text,
                    " ".repeat(a.digit_pos_chars),
                    "^".repeat(a.candidate_len),
                )
            }
            AppError::InvalidPath(p) => write!(f, "invalid path: {}", p.display()),
            AppError::Io(e) => write!(f, "{}", e),
            AppError::FailedProcessing(items) => {
                write!(f, "Failed processing some inputs")?;
                for (path, err) in items {
                    write!(f, "\n    {}: {}", path.display(), err)?;
                }
                // Original ends the inner display with a newline; main adds another.
                write!(f, "\n")
            }
        }
    }
}

impl std::error::Error for AppError {}

impl From<io::Error> for AppError {
    fn from(e: io::Error) -> Self {
        AppError::Io(e)
    }
}

impl From<regex::Error> for AppError {
    fn from(e: regex::Error) -> Self {
        AppError::InvalidRegex(e)
    }
}

// ---------- ambiguous replacement validation ----------

fn validate_replacement(replacement: &str) -> Option<Ambiguous> {
    let chars: Vec<char> = replacement.chars().collect();
    let n = chars.len();
    let mut i = 0usize;
    while i < n {
        if chars[i] != '$' {
            i += 1;
            continue;
        }
        // $$ escape
        if i + 1 < n && chars[i + 1] == '$' {
            i += 2;
            continue;
        }
        // ${...} braced: skip to closing brace if present
        if i + 1 < n && chars[i + 1] == '{' {
            if let Some(rel) = chars[i + 2..].iter().position(|&c| c == '}') {
                i = i + 2 + rel + 1;
                continue;
            } else {
                i += 1;
                continue;
            }
        }
        // Unbraced candidate: [A-Za-z0-9_]+
        let start = i + 1;
        let mut end = start;
        while end < n && (chars[end].is_ascii_alphanumeric() || chars[end] == '_') {
            end += 1;
        }
        if end > start && chars[start].is_ascii_digit() {
            let mut digit_end = start;
            while digit_end < end && chars[digit_end].is_ascii_digit() {
                digit_end += 1;
            }
            if digit_end < end {
                let digits: String = chars[start..digit_end].iter().collect();
                let remainder: String = chars[digit_end..end].iter().collect();
                // Display text: replace \t \n \r with control pictures.
                let display_text: String = replacement
                    .chars()
                    .map(|c| match c {
                        '\t' => '\u{2409}',
                        '\n' => '\u{240a}',
                        '\r' => '\u{240d}',
                        _ => c,
                    })
                    .collect();
                return Some(Ambiguous {
                    digits,
                    remainder,
                    digit_pos_chars: start, // char index of first digit
                    candidate_len: end - start,
                    display_text,
                });
            }
        }
        i = if end > start { end } else { i + 1 };
    }
    None
}

// ---------- unescape replacement ----------

fn hex_val(c: char) -> Option<u32> {
    c.to_digit(16)
}

fn unescape(input: &str) -> String {
    let chars: Vec<char> = input.chars().collect();
    let n = chars.len();
    let mut out = String::with_capacity(input.len());
    let mut i = 0usize;
    while i < n {
        let c = chars[i];
        if c != '\\' {
            out.push(c);
            i += 1;
            continue;
        }
        if i + 1 >= n {
            out.push('\\');
            i += 1;
            continue;
        }
        match chars[i + 1] {
            'n' => {
                out.push('\n');
                i += 2;
            }
            'r' => {
                out.push('\r');
                i += 2;
            }
            't' => {
                out.push('\t');
                i += 2;
            }
            '\\' => {
                out.push('\\');
                i += 2;
            }
            '\'' => {
                out.push('\'');
                i += 2;
            }
            '"' => {
                out.push('"');
                i += 2;
            }
            'x' => {
                // Need two hex digits at i+2,i+3
                if i + 3 < n {
                    if let (Some(h1), Some(h2)) = (hex_val(chars[i + 2]), hex_val(chars[i + 3])) {
                        let v = h1 * 16 + h2;
                        if let Some(ch) = char::from_u32(v) {
                            out.push(ch);
                            // Original skips one extra char after a successful
                            // \xHH sequence.
                            i += 5;
                            continue;
                        }
                    }
                }
                out.push('\\');
                i += 1;
            }
            'u' => {
                // Need four hex digits at i+2..i+6
                if i + 5 < n {
                    let mut v: u32 = 0;
                    let mut ok = true;
                    for k in 0..4 {
                        if let Some(h) = hex_val(chars[i + 2 + k]) {
                            v = v * 16 + h;
                        } else {
                            ok = false;
                            break;
                        }
                    }
                    if ok {
                        if let Some(ch) = char::from_u32(v) {
                            out.push(ch);
                            // Skip one extra char after successful \uHHHH.
                            i += 7;
                            continue;
                        }
                    }
                }
                out.push('\\');
                i += 1;
            }
            _ => {
                out.push('\\');
                i += 1;
            }
        }
    }
    out
}

// ---------- replacer ----------

struct Replacer {
    regex: Regex,
    replacement: Vec<u8>, // after unescape if not literal; raw if literal
    is_literal: bool,
    max_replacements: usize,
}

impl Replacer {
    fn new(
        find: &str,
        replace_with: &str,
        is_literal: bool,
        flags: Option<&str>,
        max_replacements: usize,
    ) -> Result<Self, AppError> {
        // Ambiguity check only in regex mode, on raw replacement, before regex build.
        if !is_literal {
            if let Some(a) = validate_replacement(replace_with) {
                return Err(AppError::Ambiguous(Box::new(a)));
            }
        }

        let mut pattern: String = if is_literal {
            regex::escape(find)
        } else {
            find.to_owned()
        };

        let flags_str: &str = flags.unwrap_or("");
        // Multi-line default: true unless 'e' anywhere.
        let mut multi_line = !flags_str.contains('e');
        let mut case_insensitive = false;
        let mut dot_matches_new_line = false;

        for ch in flags_str.chars() {
            match ch {
                'i' => case_insensitive = true,
                'c' => case_insensitive = false,
                's' => dot_matches_new_line = true,
                'w' => {
                    pattern = format!(r"\b{}\b", pattern);
                    // Creating a fresh builder (as original does) drops previous
                    // settings and the multi-line default.
                    case_insensitive = false;
                    dot_matches_new_line = false;
                    multi_line = false;
                }
                _ => {}
            }
        }

        let regex = RegexBuilder::new(&pattern)
            .case_insensitive(case_insensitive)
            .dot_matches_new_line(dot_matches_new_line)
            .multi_line(multi_line)
            .build()
            .map_err(AppError::InvalidRegex)?;

        let replacement: Vec<u8> = if is_literal {
            replace_with.as_bytes().to_vec()
        } else {
            unescape(replace_with).into_bytes()
        };

        Ok(Self {
            regex,
            replacement,
            is_literal,
            max_replacements,
        })
    }

    fn replace(&self, input: &[u8]) -> Vec<u8> {
        let limit = self.max_replacements;
        if self.is_literal {
            let repl = regex::bytes::NoExpand(self.replacement.as_slice());
            if limit == 0 {
                self.regex.replace_all(input, repl).into_owned()
            } else {
                self.regex.replacen(input, limit, repl).into_owned()
            }
        } else {
            let repl = self.replacement.as_slice();
            if limit == 0 {
                self.regex.replace_all(input, repl).into_owned()
            } else {
                self.regex.replacen(input, limit, repl).into_owned()
            }
        }
    }
}

// ---------- mmap source ----------

struct FileSource {
    ptr: *mut libc::c_void,
    map_len: usize,
    len: usize,
    _file: File,
}

// SAFETY: mmap is read-only and kept alive for the source lifetime.
impl FileSource {
    fn map(file: File) -> io::Result<Self> {
        let metadata = file.metadata()?;
        let len_u64 = metadata.len();
        let len = len_u64 as usize;
        let map_len = if len == 0 { 1 } else { len };
        // Use raw fd
        use std::os::unix::io::AsRawFd;
        let fd = file.as_raw_fd();
        let ptr = unsafe {
            libc::mmap(
                std::ptr::null_mut(),
                map_len,
                libc::PROT_READ,
                libc::MAP_PRIVATE,
                fd,
                0,
            )
        };
        if ptr == libc::MAP_FAILED {
            return Err(io::Error::last_os_error());
        }
        Ok(Self {
            ptr,
            map_len,
            len,
            _file: file,
        })
    }

    fn bytes(&self) -> &[u8] {
        if self.len == 0 {
            &[]
        } else {
            unsafe { slice::from_raw_parts(self.ptr as *const u8, self.len) }
        }
    }
}

impl Drop for FileSource {
    fn drop(&mut self) {
        unsafe {
            libc::munmap(self.ptr, self.map_len);
        }
    }
}

// ---------- file writing ----------

fn write_replaced(original_path: &Path, replaced: &[u8]) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let canonical = std::fs::canonicalize(original_path)?;
    let metadata = std::fs::metadata(&canonical)?;
    let permissions = metadata.permissions();
    let parent = canonical
        .parent()
        .map(|p| p.to_path_buf())
        .unwrap_or_else(|| PathBuf::from("/"));
    let mut tmp = NamedTempFile::new_in(&parent)?;
    tmp.write_all(replaced)?;
    // Preserve original permissions. Temp files are created 0600 by default.
    // Set them on the temp file before persisting.
    tmp.as_file().set_permissions(permissions)?;
    // Persist (rename) over the canonical destination.
    tmp.persist(&canonical).map_err(|e| e.error)?;
    Ok(())
}

// ---------- CLI ----------

fn build_cli() -> Command {
    Command::new("sd")
        .version("1.0.0")
        .about("An intuitive find & replace CLI")
        .help_template("{name} v{version}\n{about-with-newline}\n{usage-heading} {usage}\n\n{all-args}")
        .arg(
            Arg::new("find")
                .value_name("FIND")
                .required(true)
                .index(1)
                .help("The regexp or string (if using `-F`) to search for")
                .long_help("The regexp or string (if using `-F`) to search for"),
        )
        .arg(
            Arg::new("replace_with")
                .value_name("REPLACE_WITH")
                .required(true)
                .index(2)
                .help("What to replace each match with. Unless in string mode, you may use captured values like $1, $2, etc")
                .long_help("What to replace each match with. Unless in string mode, you may use captured values like $1, $2, etc"),
        )
        .arg(
            Arg::new("files")
                .value_name("FILES")
                .index(3)
                .num_args(0..)
                .action(ArgAction::Append)
                .value_parser(clap::value_parser!(PathBuf))
                .help("The path to file(s). This is optional - sd can also read from STDIN")
                .long_help("The path to file(s). This is optional - sd can also read from STDIN.\n\nNote: sd modifies files in-place by default. See documentation for examples."),
        )
        .arg(
            Arg::new("preview")
                .short('p')
                .long("preview")
                .action(ArgAction::SetTrue)
                .help("Display changes in a human reviewable format (the specifics of the format are likely to change in the future)")
                .long_help("Display changes in a human reviewable format (the specifics of the format are likely to change in the future)"),
        )
        .arg(
            Arg::new("fixed-strings")
                .short('F')
                .long("fixed-strings")
                .action(ArgAction::SetTrue)
                .help("Treat FIND and REPLACE_WITH args as literal strings")
                .long_help("Treat FIND and REPLACE_WITH args as literal strings"),
        )
        .arg(
            Arg::new("max-replacements")
                .short('n')
                .long("max-replacements")
                .value_name("LIMIT")
                .default_value("0")
                .value_parser(clap::value_parser!(usize))
                .help("Limit the number of replacements that can occur per file. 0 indicates unlimited replacements")
                .long_help("Limit the number of replacements that can occur per file. 0 indicates unlimited replacements"),
        )
        .arg(
            Arg::new("flags")
                .short('f')
                .long("flags")
                .value_name("FLAGS")
                .help("Regex flags. May be combined (like `-f mc`).")
                .long_help("Regex flags. May be combined (like `-f mc`).\n\nc - case-sensitive\n\ne - disable multi-line matching\n\ni - case-insensitive\n\nm - multi-line matching\n\ns - make `.` match newlines\n\nw - match full words only"),
        )
}

// ---------- main logic ----------

fn run(matches: &clap::ArgMatches) -> Result<(), AppError> {
    let find: &String = matches.get_one::<String>("find").expect("required");
    let replace_with: &String = matches
        .get_one::<String>("replace_with")
        .expect("required");
    let files: Vec<PathBuf> = matches
        .get_many::<PathBuf>("files")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let preview: bool = matches.get_flag("preview");
    let fixed_strings: bool = matches.get_flag("fixed-strings");
    let max_replacements: usize = *matches
        .get_one::<usize>("max-replacements")
        .unwrap_or(&0);
    let flags: Option<&String> = matches.get_one::<String>("flags");

    let replacer = Replacer::new(
        find,
        replace_with,
        fixed_strings,
        flags.map(|s| s.as_str()),
        max_replacements,
    )?;

    if files.is_empty() {
        // STDIN -> STDOUT
        let mut input: Vec<u8> = Vec::new();
        let stdin = io::stdin();
        let mut handle = stdin.lock();
        handle.read_to_end(&mut input)?;
        let replaced = replacer.replace(&input);
        let stdout = io::stdout();
        let mut out = stdout.lock();
        out.write_all(&replaced)?;
        out.flush()?;
        return Ok(());
    }

    // Validate all paths first.
    for path in &files {
        if !path.exists() {
            return Err(AppError::InvalidPath(path.clone()));
        }
    }

    // Load all files (mmap) before making any changes.
    let mut sources: Vec<FileSource> = Vec::with_capacity(files.len());
    for path in &files {
        let file = File::open(path)?;
        let source = FileSource::map(file)?;
        sources.push(source);
    }

    if preview {
        let stdout = io::stdout();
        let mut out = stdout.lock();
        let multiple = files.len() > 1;
        for (path, source) in files.iter().zip(sources.iter()) {
            if multiple {
                // Header uses the path as supplied.
                write!(out, "----- FILE {} -----\n", path.display())?;
            }
            let replaced = replacer.replace(source.bytes());
            out.write_all(&replaced)?;
        }
        out.flush()?;
        return Ok(());
    }

    // In-place
    let mut failures: Vec<(PathBuf, Box<dyn std::error::Error + Send + Sync>)> = Vec::new();
    for (path, source) in files.iter().zip(sources.iter()) {
        let replaced = replacer.replace(source.bytes());
        if let Err(e) = write_replaced(path, &replaced) {
            failures.push((path.clone(), e));
        }
    }
    if !failures.is_empty() {
        return Err(AppError::FailedProcessing(failures));
    }
    Ok(())
}

fn main() -> ExitCode {
    let matches = build_cli().get_matches();
    match run(&matches) {
        Ok(()) => ExitCode::from(0),
        Err(e) => {
            eprintln!("error: {}", e);
            ExitCode::from(1)
        }
    }
}
RS
"}

