//! Minimal terminal-size support for Unix terminals.
//!
//! This provides the small API surface used by clap's `wrap_help`
//! support: querying the current terminal dimensions.

/// Terminal width in columns.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Width(pub u16);

/// Terminal height in rows.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Height(pub u16);

#[repr(C)]
#[derive(Default)]
struct Winsize {
    ws_row: libc::c_ushort,
    ws_col: libc::c_ushort,
    ws_xpixel: libc::c_ushort,
    ws_ypixel: libc::c_ushort,
}

fn size_of_fd(fd: libc::c_int) -> Option<(Width, Height)> {
    let mut winsize = Winsize::default();
    let result = unsafe { libc::ioctl(fd, libc::TIOCGWINSZ, &mut winsize) };
    if result != 0 || winsize.ws_col == 0 {
        return None;
    }
    Some((Width(winsize.ws_col), Height(winsize.ws_row)))
}

/// Returns the size of the terminal, if it can be determined.
///
/// Standard output is checked first, followed by standard error and
/// standard input, matching the usual convention for terminal queries.
pub fn terminal_size() -> Option<(Width, Height)> {
    size_of_fd(libc::STDOUT_FILENO)
        .or_else(|| size_of_fd(libc::STDERR_FILENO))
        .or_else(|| size_of_fd(libc::STDIN_FILENO))
}
