import pathlib
p=pathlib.Path("src/main.rs")
s=p.read_text()
# Add clap error handling in main
old = """fn main() -> ExitCode {
    let matches = build_cli().get_matches();"""
new = """fn main() -> ExitCode {
    let mut cli = build_cli();
    let matches = match cli.try_get_matches_mut() {
        Ok(m) => m,
        Err(e) => handle_clap_error(e),
    };"""
assert old in s
s=s.replace(old,new)

handler = '''
fn handle_clap_error(e: clap::Error) -> ! {
    // The original binary (built against an earlier clap) renders the
    // "smart usage" for a suggested user option as a list of all user
    // arguments in angle brackets. Newer clap renders it differently;
    // reproduce the observed form for those cases.
    let rendered = e.render();
    let plain = rendered.to_string();
    let should_rewrite = e.kind() == clap::error::ErrorKind::UnknownArgument
        && plain.contains("a similar argument exists: '--preview'")
        || e.kind() == clap::error::ErrorKind::UnknownArgument
            && (plain.contains("a similar argument exists: '--fixed-strings'")
                || plain.contains("a similar argument exists: '--max-replacements'")
                || plain.contains("a similar argument exists: '--flags'"));
    if should_rewrite {
        // Bin name is the first token after "Usage: " in the plain rendering.
        let mut bin_name = "sd";
        for line in plain.lines() {
            if let Some(rest) = line.strip_prefix("Usage: ") {
                if let Some(first) = rest.split(' ').next() {
                    bin_name = first;
                }
                break;
            }
        }
        let ansi = rendered.ansi().to_string();
        let new_usage = format!(
            "\\x1b[1m\\x1b[4mUsage:\\x1b[0m \\x1b[1m{}\\x1b[0m <--preview|--fixed-strings|--max-replacements <LIMIT>|--flags <FLAGS>|FIND|REPLACE_WITH|FILES>",
            bin_name
        );
        let mut out_text = ansi;
        if let Some(usage_pos) = out_text.find("Usage:") {
            let line_start = out_text[..usage_pos].rfind('\\n').map(|i| i + 1).unwrap_or(0);
            let line_end = out_text[usage_pos..]
                .find('\\n')
                .map(|i| usage_pos + i)
                .unwrap_or(out_text.len());
            out_text.replace_range(line_start..line_end, &new_usage);
        }
        let mut stream = anstream::stderr();
        let _ = stream.write_all(out_text.as_bytes());
        let _ = stream.flush();
        std::process::exit(e.exit_code());
    }
    e.exit()
}

'''
# Insert handler before fn main definition
s=s.replace("\nfn main() -> ExitCode {", handler+"\nfn main() -> ExitCode {")
p.write_text(s)
